-- Lux Collection starter catalogue: 163 distinct vehicle models.
-- This idempotent upsert can be run again without duplicating catalogue entries.
ON CONFLICT (make, model) DO UPDATE SET
  image = EXCLUDED.image,
  description = EXCLUDED.description,
  category = EXCLUDED.category,
  price_per_day = EXCLUDED.price_per_day,
  seats = EXCLUDED.seats,
  transmission = EXCLUDED.transmission,
  highlight = EXCLUDED.highlight,
  service_areas = EXCLUDED.service_areas,
  featured = EXCLUDED.featured,
  sort_order = EXCLUDED.sort_order,
  updated_at = now();

SELECT count(*) AS lux_catalogue_vehicles, count(*) FILTER (WHERE active AND fleet_status='available') AS available_vehicles FROM public.cars;

-- Seed real 2027 911 Carrera Coupé trims when this listing has no operator-entered versions.
-- Rental rates are Lux Collection rates, scaled from the existing Carrera listing rate.
UPDATE public.cars
SET variants = jsonb_build_array(
  jsonb_build_object(
    'id','carrera','name','Carrera','design','3.0-litre flat-six · rear-wheel drive · PDK',
    'description','The classic 911 balance of everyday usability and sports-car performance.',
    'pricePerDay',715,
    'performance',jsonb_build_object('power','394 PS','acceleration','4.1 sec (0–62 mph)','topSpeed','183 mph','drivetrain','Rear-wheel drive','engine','3.0-litre twin-turbo flat-six'),
    'specs',jsonb_build_object('seats','4','transmission','8-speed PDK automatic','fuel','Petrol','bodyStyle','Coupé'),
    'features',jsonb_build_array('Rear-engine layout','Sport Chrono compatible')
  ),
  jsonb_build_object(
    'id','carrera-t','name','Carrera T','design','Lightweight purist · 6-speed manual · rear-wheel drive',
    'description','A lighter, more driver-focused Carrera with a manual gearbox.',
    'pricePerDay',795,
    'performance',jsonb_build_object('power','394 PS','acceleration','4.5 sec (0–62 mph)','topSpeed','183 mph','drivetrain','Rear-wheel drive','engine','3.0-litre twin-turbo flat-six'),
    'specs',jsonb_build_object('seats','2','transmission','6-speed manual','fuel','Petrol','bodyStyle','Coupé'),
    'features',jsonb_build_array('Reduced sound insulation','Lightweight glass')
  ),
  jsonb_build_object(
