    'pricePerDay',830,
    'performance',jsonb_build_object('power','480 PS','acceleration','3.5 sec (0–62 mph)','topSpeed','191 mph','drivetrain','Rear-wheel drive','engine','3.0-litre twin-turbo flat-six'),
