    'performance',jsonb_build_object('power','480 PS','acceleration','3.3 sec (0–62 mph)','topSpeed','191 mph','drivetrain','All-wheel drive','engine','3.0-litre twin-turbo flat-six'),
    'specs',jsonb_build_object('seats','4','transmission','8-speed PDK automatic','fuel','Petrol','bodyStyle','Coupé'),
    'features',jsonb_build_array('All-wheel drive','Porsche Doppelkupplung')
  ),
  jsonb_build_object(
    'id','carrera-gts','name','Carrera GTS','design','T-Hybrid · 541 PS · rear-wheel drive · PDK',
    'description','The range-topping GTS pairs a 3.6-litre flat-six with Porsche T-Hybrid technology.',
    'pricePerDay',950,
    'performance',jsonb_build_object('power','541 PS combined','acceleration','3.0 sec (0–62 mph)','topSpeed','194 mph','drivetrain','Rear-wheel drive','engine','3.6-litre T-Hybrid flat-six'),
    'specs',jsonb_build_object('seats','4','transmission','8-speed PDK automatic','fuel','Petrol hybrid','bodyStyle','Coupé'),
    'features',jsonb_build_array('T-Hybrid technology','Rear-axle steering','PASM sports chassis')
