  jsonb_build_object(
    'id','carrera-4-gts','name','Carrera 4 GTS','design','T-Hybrid · 541 PS · all-wheel drive · PDK',
    'description','GTS T-Hybrid performance with rear-biased all-wheel drive.',
    'pricePerDay',990,
    'performance',jsonb_build_object('power','541 PS combined','acceleration','3.0 sec (0–62 mph)','topSpeed','194 mph','drivetrain','All-wheel drive','engine','3.6-litre T-Hybrid flat-six'),
    'specs',jsonb_build_object('seats','4','transmission','8-speed PDK automatic','fuel','Petrol hybrid','bodyStyle','Coupé'),
    'features',jsonb_build_array('T-Hybrid technology','Rear-biased all-wheel drive','PASM sports chassis')
